css:
.sh__rule { display: block; width: 3.5rem; height: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--bff-leaf, #6b8e36), var(--bff-gold, #eec02b)); margin-bottom: clamp(1.4rem, 3vw, 2.2rem); }
.sh__h { margin: 0 0 .5em; font-family: var(--os-font-heading); font-weight: 400; font-size: clamp(2.1rem, 1.2rem + 3.4vw, 3.7rem); line-height: 1.08; letter-spacing: -0.015em; text-wrap: balance; color: var(--os-color-heading); }
.sh__sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.sh__lead { margin: 0; max-width: 34ch; font-family: var(--os-font-heading); font-size: clamp(1.5rem, 1rem + 1.8vw, 2.3rem); line-height: 1.25; letter-spacing: -0.01em; text-wrap: balance; color: var(--os-color-heading); }
